insert into cellar.products (type, status, source, specs, name, brand, brand_family, expression, producer, producer_id, proof, age_years, age_label, nas, expression_type, mash_style, mash_bill, spirit_type, bottled_in_bond, barrel_proof, finish, msrp_usd, is_core_range, catalog_included, aliases, image_url, source_url, source_checked_at, rarity)
select 'bourbon', 'confirmed', 'maker', case when r.img is null then '{}'::jsonb else jsonb_build_object('source_image_url', r.img) end, r.n, r.f, r.f, r.x, r.pr, r.mk::uuid, r.p, r.ay, r.al, r.nas, r.et::cellar.expression_type, r.ms::cellar.mash_style, r.mb, r.st::cellar.spirit_type, r.bib, r.bp, r.fin, r.msrp, r.core, true, coalesce(r.al2, '{}'::text[]), null, r.u, now(), r.rar::cellar.rarity
from jsonb_to_recordset($j$[{"n":"Two Souls J. Henry & Sons 7 Year Rum Cask Finished Bourbon","rar":"limited","f":"Two Souls","x":"J. Henry & Sons 7 Year Rum Cask Finished Bourbon","p":115.32,"ay":7.25,"al":"7 yr 3 mo","nas":false,"et":"standard","ms":"traditional","mb":"64% Red Corn, 14% Wheat, 14% Rye, 8% Malted Barley","st":"bourbon","bib":false,"bp":true,"fin":"Rum Cask","msrp":null,"core":false,"al2":[],"img":"https://cdn.shopify.com/s/files/1/0605/9461/8542/files/9.png?v=1779321249","u":"https://twosoulsspirits.com/products/j-henry-sons-7-year-rum-finished-bourbon","pr":"Two Souls Spirits","mk":null},{"n":"Two Souls J. Henry & Sons 7 Year Rum Cask Finished Rye","rar":"limited","f":"Two Souls","x":"J. Henry & Sons 7 Year Rum Cask Finished Rye","p":124.58,"ay":7.33,"al":"7 yr 4 mo","nas":false,"et":"standard","ms":"rye","mb":"64% Rye, 14% Wheat, 14% Corn, 8% Malted Barley","st":"rye","bib":false,"bp":true,"fin":"Rum Cask","msrp":null,"core":false,"al2":[],"img":"https://cdn.shopify.com/s/files/1/0605/9461/8542/files/4_97eabead-a914-4aab-abf7-8c8230bdf9d7.png?v=1779319840","u":"https://twosoulsspirits.com/products/j-henry-sons-7-year-rum-cask-rye","pr":"Two Souls Spirits","mk":null}]$j$::jsonb) as r(n text, f text, x text, p numeric, ay numeric, al text, nas bool, et text, ms text, mb text, st text, bib bool, bp bool, fin text, msrp numeric, core bool, al2 text[], img text, u text, pr text, mk text, rar text)
where not exists (select 1 from cellar.products e where e.type = 'bourbon' and e.merged_into is null and coalesce(e.brand_family, '') = coalesce(r.f, '') and coalesce(e.expression, '') = coalesce(r.x, '') and coalesce(e.release_label, '') = '');
